sp_widget.client_script:
api.controller=function($scope){

var c=this;

c.filtered=
angular.copy(
c.data.employees||[]
);

$scope.$watch(

function(){

return [

$scope.page.searchText,

$scope.page.department,

$scope.page.status

];

},

function(){

var text=
($scope.page.searchText||'')
.toLowerCase();

var dept=
$scope.page.department||'';

var status=
$scope.page.status||'';

c.filtered=
c.data.employees.filter(

function(emp){

var textMatch=

!text ||

(emp.name||'')
.toLowerCase()
.indexOf(text)>-1 ||

(emp.designation||'')
.toLowerCase()
.indexOf(text)>-1;

var deptMatch=

!dept ||

emp.department==
dept;

var statusMatch=

!status ||

(emp.status||'')
.toLowerCase()===(status||'').toLowerCase();
return (

textMatch &&
deptMatch &&
statusMatch

);

}

);

},

true

);

};

sp_widget.css:
.directory-grid{

display:grid;

grid-template-columns:
repeat(
auto-fill,
minmax(
280px,
1fr
)
);

gap:28px;

}



.employee-card{

background:white;

padding:30px;

border-radius:28px;

box-shadow:

0 18px 40px

rgba(
0,
0,
0,
.05
);

transition:.25s;

}



.employee-card:hover{

transform:
translateY(-6px);

}



.avatar{

width:72px;

height:72px;

border-radius:22px;

background:

linear-gradient(
135deg,
#2758FF,
#4A7DFF
);

display:flex;

align-items:center;

justify-content:center;

color:white;

font-size:30px;

font-weight:900;

}



.name{

margin-top:22px;

font-size:28px;

font-weight:900;

}



.designation{

margin-top:10px;

color:#5F7198;

}



.department{

margin-top:8px;

color:#8F9DBA;

}



.profile-btn{

display:flex;

margin-top:24px;

height:54px;

align-items:center;

justify-content:center;

border-radius:16px;

background:

#2455FF;

color:white;

text-decoration:none;

font-weight:800;

}
.empty{

grid-column:
1/-1;

padding:
80px;

text-align:
center;

font-size:
28px;

font-weight:
800;

color:
#7A89A8;

}

sp_widget.script:
(function(){

data.employees=[];

var gr=
new GlideRecord(
'x_1902481_employ_0_employee'
);

gr.orderBy(
'name'
);

gr.query();

while(
gr.next()
){

var emp=
gr.getDisplayValue();

data.employees.push({

sys_id:
gr.getUniqueValue(),

name:
emp,

designation:
gr.getDisplayValue(
'designation'
),

department:
gr.getDisplayValue(
'department'
),

initial:
(emp.charAt(0)||'E')

});

}

})();
